<script setup>
import {ref,computed,onMounted,onBeforeUnmount} from 'vue';
const savedId=ref('');try{savedId.value=sessionStorage.getItem('promoAdmin.benchmarkId')||'';}catch{}
const prompts=ref([]),supported=ref([]),type=ref('promo_overview_parser'),candidate=ref(''),input=ref(''),result=ref(null),error=ref(''),busy=ref(false);let alive=true;
const baseline=computed(()=>prompts.value.find(p=>p.type===type.value&&p.status==='active'));
const candidates=computed(()=>prompts.value.filter(p=>p.type===type.value&&p.status==='validated'));
async function api(body){const response=await fetch('/api/admin-prompt-benchmarks',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-Builder-Task-Id':body.benchmarkId},body:JSON.stringify(body)}),payload=await response.json();if(!response.ok)throw Error(payload.error||'비교 실행 실패');return payload;}
async function run(){if(busy.value)return;busy.value=true;error.value='';try{const continuing=result.value?.status==='running',id=continuing?result.value.id:crypto.randomUUID();savedId.value=id;try{sessionStorage.setItem('promoAdmin.benchmarkId',id);}catch{}let response;if(!continuing){const fixture=JSON.parse(input.value);response=await api({operation:'start',benchmarkId:id,baselineId:baseline.value?.id,candidateId:candidate.value,input:fixture});result.value=response.benchmark;}for(let step=0;step<90&&alive&&result.value.status==='running';step++){response=await api({operation:'advance',benchmarkId:id});if(!alive)return;result.value=response.benchmark;if(response.pending)await new Promise(resolve=>setTimeout(resolve,1000));}if(result.value.status==='running')error.value='비교가 진행 중입니다. 작업 ID를 보관하고 결과를 다시 조회하세요.';}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function restore(){if(!savedId.value)return;busy.value=true;error.value='';try{const response=await api({operation:'read',benchmarkId:savedId.value});result.value=response.benchmark;}catch(e){error.value=e.message;}finally{busy.value=false;}}
function example(){input.value=JSON.stringify({variables:{generationMode:'new-draft',naturalLanguage:'신규 회원 대상 브랜드 소개 프로모션을 만들어줘. 제공하지 않은 금액과 기간은 만들지 마.',allowedValuesJson:JSON.stringify({promotionPurposes:['할인쿠폰','경품','이벤트','기타'],audiences:['신규','기존고객','일반고객'],campaignTones:['활기찬','진중함','럭셔리','프리미엄','긴급함','친근함']}),currentOverviewJson:'{}',productCatalogJson:'[]',localeAndMarketJson:'{"locale":"ko-KR","market":""}'}},null,2);}
onMounted(async()=>{try{const response=await fetch('/api/admin-prompt-benchmarks?operation=prompts',{credentials:'same-origin',cache:'no-store'}),payload=await response.json();if(!response.ok)throw Error(payload.error||'목록 조회 실패');prompts.value=payload.prompts;supported.value=payload.supported;example();}catch(e){error.value=e.message;}});onBeforeUnmount(()=>{alive=false;});
</script>
<template>
<section class="benchmark-manager" aria-labelledby="benchmark-title"><h2 id="benchmark-title">모델·프롬프트 비교</h2><p>같은 입력으로 현재 활성 버전과 검증된 후보를 각각 한 번 호출합니다. 실제 모델 비용이 발생하며 Preview/테스트 환경에서만 실행할 수 있습니다. 설정은 자동 활성화하지 않습니다.</p>
 <div class="benchmark-form"><label>단계<select v-model="type" :disabled="busy" aria-label="비교 단계"><option v-for="name in supported" :key="name" :value="name">{{name}}</option></select></label><p>기준: {{baseline?`${baseline.name} v${baseline.version} · ${baseline.model}`:'활성 버전 없음'}}</p><label>검증된 후보<select v-model="candidate" :disabled="busy" aria-label="비교 후보"><option value="">선택</option><option v-for="item in candidates" :key="item.id" :value="item.id">{{item.name}} v{{item.version}} · {{item.model}}</option></select></label><label>입력 케이스 JSON<textarea v-model="input" :disabled="busy" rows="16" spellcheck="false" aria-label="비교 입력 JSON"></textarea></label><p>variables는 해당 프롬프트의 필수 변수를 모두 포함해야 합니다. 페이지 단계에는 실제 활성 토큰의 context와 단계에 따른 page/state/group을 함께 입력합니다. 샘플은 요청 요약용입니다.</p><button type="button" :disabled="busy||(result?.status!=='running'&&(!baseline||!candidate))" @click="run">{{busy?'비교 진행 중':result?.status==='running'?'저장된 비교 이어가기':'같은 입력으로 2개 버전 비교'}}</button></div>
 <label>저장된 비교 작업 ID<input v-model="savedId" :disabled="busy"></label><button type="button" :disabled="busy||!savedId" @click="restore">비교 결과 불러오기</button>
 <p v-if="error" role="alert">{{error}}</p><section v-if="result" aria-label="비교 결과"><h3>비교 결과 · {{result.status}}</h3><p>작업 ID: {{result.id}}</p><button type="button" :disabled="busy" @click="restore">저장 결과 다시 조회</button><div class="benchmark-results"><article v-for="variant in result.results" :key="variant.variant"><h4>{{variant.variant==='baseline'?'현재 활성':'검증 후보'}} · {{variant.ok?'형식 검증 통과':'실패'}}</h4><p>{{variant.model}} · {{variant.durationMs==null?'—':`${(variant.durationMs/1000).toFixed(2)}초`}}</p><p v-if="!variant.ok">{{variant.errorCode}} · {{variant.message}}</p><img v-if="variant.imageUrl" :src="variant.imageUrl" alt="비교용 생성 이미지"><pre v-else>{{JSON.stringify(variant.preview||{},null,2)}}</pre><p>사용량: {{JSON.stringify(variant.usage||{})}}</p></article></div><p>형식·토큰·허용 범위 검증은 디자인 미감·브랜드 적합성의 통과를 의미하지 않습니다. 실제 결과를 비교한 뒤 기존 프롬프트 관리에서 별도로 활성화하세요.</p></section>
</section>
</template>
<style scoped>.benchmark-manager{padding:20px;min-width:0}.benchmark-form{display:grid;gap:12px;max-width:1000px}.benchmark-form label{display:grid;gap:6px}.benchmark-form select,.benchmark-form textarea{padding:9px;max-width:100%;min-width:0}.benchmark-results{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.benchmark-results article{border:1px solid #d8dce3;padding:16px;min-width:0}.benchmark-results pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:500px;overflow:auto}.benchmark-results img{max-width:100%;height:auto}.benchmark-manager p{overflow-wrap:anywhere}.benchmark-manager button{padding:8px 12px}@media(max-width:700px){.benchmark-results{grid-template-columns:1fr}}</style>
